import pandas as pd

def clean(df):
    df = df.copy()

    # Normalize text label columns
    for col in ["Category", "Region"]:
        if col in df.columns:
            df[col] = df[col].astype("string").str.strip()

    # Fix category label variants
    category_map = {
        "Office Suplies": "Office Supplies",
        "Furnture": "Furniture",
    }
    if "Category" in df.columns:
        df["Category"] = df["Category"].replace(category_map)

    # Remove exact duplicate rows
    df = df.drop_duplicates().reset_index(drop=True)

    # Ensure numeric columns are numeric
    for col in ["Quantity", "Price", "Revenue"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")

    # Quantity must be positive; treat negative values as sign-entry errors
    if "Quantity" in df.columns:
        df["Quantity"] = df["Quantity"].abs()

    # Recompute Revenue from corrected Quantity and Price
    if all(c in df.columns for c in ["Quantity", "Price", "Revenue"]):
        df["Revenue"] = df["Quantity"] * df["Price"]

    return df


def answer(df):
    d = clean(df)
    d = d.dropna(subset=["Category", "Price"])
    result = d.groupby("Category", dropna=True)["Price"].mean().to_dict()
    return {str(k): float(v) for k, v in result.items()}
